package dustin.cex.domains.kyc;
import dustin.cex.domains.account.*;
import dustin.cex.domains.mail.*;
import dustin.cex.domains.auth.model.dto.SigninRequest;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/** 변경 확정·보안 통지 예약·실제 SMTP·재로그인 후 본인 이력과 실패 원자성을 검증한다. */
class CustomerPasswordNoticeIntegrationTest extends CustomerMailTestSupport {
    static final String OLD="security-test-password",NEW="independent-new-passphrase-2026";
    @Autowired CustomerPasswordChange changes;@Autowired CustomerPasswordHistory history;@Autowired CustomerEmailVerification email;@Autowired CustomerServiceMail preferences;@Autowired CustomerMailRetryService retries;
    UUID job(UUID ref){return jdbc.queryForObject("SELECT id FROM customer_mail_jobs WHERE reference_id=?",UUID.class,ref);}
    void verified(){var r=email.request(customer.getId(),sid,UUID.randomUUID());String token=outbox.open(job(r.challengeId())).token();outbox.finish(outbox.claim(),"SUPPRESSED");email.confirm(customer.getId(),sid,r.challengeId(),token);}
    CustomerPasswordChange.Receipt change(){return changes.change(customer.getId(),sid,new CustomerPasswordChange.Input(OLD,NEW));}
    void login(){var r=auth.signin(new SigninRequest(customer.getEmail(),NEW));sid=UUID.fromString(jwt.verifyAccessToken(r.getAccessToken()).get("sid",String.class));customerAccess=r.getAccessToken();}
    @Test void verifiedAddressReceivesSecurityMailWithoutServiceOptIn() throws Exception {verified();assertFalse(preferences.own(customer.getId(),sid).enabled());var r=change();UUID id=job(r.id());dispatcher.dispatchOnce();assertEquals("SMTP_ACCEPTED",outbox.state(id).status());assertTrue(server().waitForIncomingEmail(3000,1));var message=server().getReceivedMessages()[0];assertEquals("비밀번호 변경 안내",message.getSubject());String body=(String)message.getContent();assertTrue(body.contains("/account/security"));for(String secret:List.of(OLD,NEW,"passwordHash","token=",sid.toString()))assertFalse(body.contains(secret));}
    @Test void unverifiedAddressHasHistoryButNoExternalMail(){var r=change();assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE reference_id=?",Long.class,r.id()));login();assertEquals(r.id(),history.own(customer.getId(),sid,null).items().getFirst().id());}
    @Test void oldSessionCannotReadHistoryButNewLoginCan(){var r=change();assertThrows(ResponseStatusException.class,()->history.own(customer.getId(),sid,null));login();var page=history.own(customer.getId(),sid,null);assertEquals(List.of(new CustomerPasswordHistory.Change(r.id(),r.changedAt())),page.items());String raw=json.writeValueAsString(page);for(String secret:List.of(OLD,NEW,"sessionId","userId","passwordHash",customer.getEmail()))assertFalse(raw.contains(secret));}
    @Test void addressChangeBeforeDispatchSuppressesOriginalRecipient(){verified();var r=change();var u=users.findById(customer.getId()).orElseThrow();u.setEmail(UUID.randomUUID()+"@other.invalid");users.saveAndFlush(u);dispatcher.dispatchOnce();assertEquals("SUPPRESSED",outbox.state(job(r.id())).status());assertEquals(0,server().getReceivedMessages().length);}
    @Test void disabledAccountStillGetsVerifiedSecurityWarning(){verified();var r=change();var u=users.findById(customer.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);dispatcher.dispatchOnce();assertEquals("SMTP_ACCEPTED",outbox.state(job(r.id())).status());}
    @Test void mailReservationFailureRollsBackPasswordSessionsAndHistory(){verified();doThrow(new IllegalStateException("격리 예약 감사 실패")).when(audit).record(any(),eq("CUSTOMER_MAIL_QUEUED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,this::change);reset(audit);assertTrue(passwords.verify(OLD,users.findById(customer.getId()).orElseThrow().getPasswordHash()));assertFalse(tokens.findBySessionId(sid).orElseThrow().getRevoked());assertTrue(history.own(customer.getId(),sid,null).items().isEmpty());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE user_id=? AND kind='PASSWORD_CHANGED'",Long.class,customer.getId()));}
    @Test void passwordAuditFailureAlsoRollsBackQueuedMail(){verified();doThrow(new IllegalStateException("격리 변경 감사 실패")).when(audit).record(any(),eq("CUSTOMER_PASSWORD_CHANGED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,this::change);reset(audit);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE user_id=? AND kind='PASSWORD_CHANGED'",Long.class,customer.getId()));assertFalse(tokens.findBySessionId(sid).orElseThrow().getRevoked());}
    @Test void historyAuditFailurePreventsResponse(){change();login();doThrow(new IllegalStateException("격리 이력 감사 실패")).when(audit).record(any(),eq("CUSTOMER_PASSWORD_HISTORY_READ"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->history.own(customer.getId(),sid,null));}
    @Test void foreignOrOperatorSessionCannotReadCustomerHistory(){assertThrows(ResponseStatusException.class,()->history.own(maker.user().getId(),maker.sid(),null));assertThrows(ResponseStatusException.class,()->history.own(customer.getId(),maker.sid(),null));}
    @Test void sameTimestampHistoryUsesIdCursorWithoutOmission(){Instant at=Instant.now().minusSeconds(1).truncatedTo(java.time.temporal.ChronoUnit.MICROS);for(int i=0;i<29;i++)jdbc.update("INSERT INTO customer_password_changes(id,user_id,session_id,changed_at) VALUES(?,?,?,?)",UUID.randomUUID(),customer.getId(),UUID.randomUUID(),Timestamp.from(at));var first=history.own(customer.getId(),sid,null);var next=history.own(customer.getId(),sid,first.next());var ids=new HashSet<UUID>();first.items().forEach(x->assertTrue(ids.add(x.id())));next.items().forEach(x->assertTrue(ids.add(x.id())));assertEquals(29,ids.size());assertNull(next.next());}
    @Test void invalidCursorIsRejected(){for(var c:List.of(new CustomerPasswordHistory.Cursor(null,UUID.randomUUID()),new CustomerPasswordHistory.Cursor(Instant.now().plusSeconds(600),UUID.randomUUID())))assertEquals(400,assertThrows(ResponseStatusException.class,()->history.own(customer.getId(),sid,c)).getStatusCode().value());}
    @Test void operatorsCannotReleaseExhaustedSecurityMail(){verified();var r=change();UUID id=job(r.id());for(int i=0;i<5;i++){outbox.finish(outbox.claim(),"SMTP_UNKNOWN");jdbc.update("UPDATE customer_mail_delivery SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE job_id=?",id);}assertEquals("EXHAUSTED",outbox.state(id).status());assertThrows(ResponseStatusException.class,()->retries.propose(maker.user().getId(),maker.sid(),id,UUID.randomUUID(),checker.user().getId()));}
    @Test void actualHttpHistoryRequiresFreshValidCustomerSession() throws Exception {change();login();mvc.perform(get("/api/customer/security/password-changes").header("Authorization","Bearer "+customerAccess)).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store"))).andExpect(jsonPath("$.items.length()").value(1));mvc.perform(get("/api/customer/security/password-changes").header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());}
}
